"""Post-process the stubs of streampu._ext generated by pybind11-stubgen.

Called by scripts/generate_stubs.sh. It fixes two side effects of generating the stubs
after `import streampu`, which adds Python methods to the C++ classes:

- names used in the annotations of these methods (e.g. `SocketLike`) are not imported
  in the stubs: the missing imports are added;
- their docstrings are re-indented by pybind11-stubgen as a whole, so that every line
  but the first one is indented too much: the extra indentation is removed so that the
  sections (Args, Returns...) are recognized by mkdocstrings.

Usage: python scripts/fix_stubs.py STUBS_FOLDER
"""

from __future__ import annotations

import ast
import builtins
import sys
from pathlib import Path

# Names that may appear in the annotations of the Python methods, and how to import them
IMPORTS = {
    "SocketLike": "from streampu._typing import SocketLike",
    "np": "import numpy as np",
    "Socket": "from streampu._ext.core import Socket",
}


def _defined_names(tree: ast.Module) -> set:
    names = set(dir(builtins))
    for node in ast.walk(tree):
        if isinstance(node, (ast.ClassDef, ast.FunctionDef)):
            names.add(node.name)
        elif isinstance(node, ast.Import):
            names.update((a.asname or a.name).split(".")[0] for a in node.names)
        elif isinstance(node, ast.ImportFrom):
            names.update(a.asname or a.name for a in node.names)
        elif isinstance(node, (ast.Assign, ast.AnnAssign)):
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            names.update(t.id for t in targets if isinstance(t, ast.Name))
    return names


def _annotation_names(tree: ast.Module) -> set:
    names = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            args = node.args
            params = args.posonlyargs + args.args + args.kwonlyargs + [a for a in (args.vararg, args.kwarg) if a]
            for ann in [p.annotation for p in params] + [node.returns]:
                if ann is not None:
                    names.update(n.id for n in ast.walk(ann) if isinstance(n, ast.Name))
    return names


def fix_imports(source: str) -> str:
    tree = ast.parse(source)
    missing = sorted((_annotation_names(tree) - _defined_names(tree)) & IMPORTS.keys())
    if not missing:
        return source
    lines = source.split("\n")
    position = next((i + 1 for i, line in enumerate(lines) if line.startswith("from __future__")), 0)
    lines[position:position] = [IMPORTS[name] for name in missing]
    return "\n".join(lines)


def fix_docstrings(source: str) -> str:
    tree = ast.parse(source)
    lines = source.split("\n")
    for node in ast.walk(tree):
        if not isinstance(node, (ast.ClassDef, ast.FunctionDef)) or not node.body:
            continue
        first = node.body[0]
        if not (isinstance(first, ast.Expr) and isinstance(first.value, ast.Constant)):
            continue
        if not isinstance(first.value.value, str):
            continue
        start, end = first.lineno - 1, first.end_lineno - 1
        if lines[start].strip() != '"""' or lines[end].strip() != '"""':
            continue
        content = [i for i in range(start + 1, end) if lines[i].strip()]
        if len(content) < 2:
            continue
        indent = lambda line: len(line) - len(line.lstrip())  # noqa: E731
        first_indent = indent(lines[content[0]])
        rest_indent = min(indent(lines[i]) for i in content[1:])
        extra = rest_indent - first_indent
        if extra <= 0:
            continue
        for i in range(content[0] + 1, end):
            if lines[i].strip():
                lines[i] = lines[i][extra:]
    return "\n".join(lines)


def main(folder: str) -> None:
    for path in sorted(Path(folder).rglob("*.pyi")):
        source = path.read_text()
        fixed = fix_docstrings(fix_imports(source))
        if fixed != source:
            path.write_text(fixed)
            print(f"fixed {path}")


if __name__ == "__main__":
    main(sys.argv[1])
